using Microsoft.EntityFrameworkCore; using VetCommission.Application.Common.Results; using VetCommission.Application.Features.Procedures; using VetCommission.Infrastructure.Persistence.Generated; using VetCommission.Infrastructure.Persistence.Generated.Entities;
namespace VetCommission.Infrastructure.Clinics;
public sealed class ProcedureRepository(VetCommissionDbContext db):IProcedureRepository{static ProcedureDto D(Procedure x)=>new(x.Id,x.TenantId,x.ClinicId,x.CategoryId,x.Code,x.Name,x.Description,x.DefaultValue,x.Active);public async Task<PagedResult<ProcedureDto>> ListAsync(Guid t,Guid c,int p,int s,string? search,Guid? category,CancellationToken ct){var q=db.Procedures.AsNoTracking().Where(x=>x.TenantId==t&&x.ClinicId==c);if(category.HasValue)q=q.Where(x=>x.CategoryId==category);if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.Name.ToLower().Contains(search.Trim().ToLower()));var n=await q.CountAsync(ct);var i=await q.OrderBy(x=>x.Name).ThenBy(x=>x.Id).Skip((p-1)*s).Take(s).ToArrayAsync(ct);return new(i.Select(D).ToArray(),p,s,n);}public async Task<ProcedureDto?> GetAsync(Guid t,Guid c,Guid id,CancellationToken ct){var e=await db.Procedures.AsNoTracking().SingleOrDefaultAsync(x=>x.TenantId==t&&x.ClinicId==c&&x.Id==id,ct);return e is null?null:D(e);}public async Task<ProcedureDto?> SaveAsync(Guid t,Guid c,SaveProcedureCommand v,CancellationToken ct){if(!await db.ProcedureCategories.AnyAsync(x=>x.TenantId==t&&x.ClinicId==c&&x.Id==v.CategoryId,ct))return null;var e=v.Id is Guid id?await db.Procedures.SingleOrDefaultAsync(x=>x.TenantId==t&&x.ClinicId==c&&x.Id==id,ct):new Procedure{Id=Guid.NewGuid(),TenantId=t,ClinicId=c,Active=true,CreatedAtUtc=DateTime.UtcNow};if(e is null)return null;e.CategoryId=v.CategoryId;e.Code=string.IsNullOrWhiteSpace(v.Code)?null:v.Code.Trim();e.Name=v.Name.Trim();e.Description=string.IsNullOrWhiteSpace(v.Description)?null:v.Description.Trim();e.DefaultValue=v.DefaultValue;e.UpdatedAtUtc=DateTime.UtcNow;if(db.Entry(e).State==EntityState.Detached)db.Procedures.Add(e);await db.SaveChangesAsync(ct);return D(e);}public async Task<ProcedureDto?> SetActiveAsync(Guid t,Guid c,Guid id,bool active,CancellationToken ct){var e=await db.Procedures.SingleOrDefaultAsync(x=>x.TenantId==t&&x.ClinicId==c&&x.Id==id,ct);if(e is null)return null;e.Active=active;e.InactivatedAtUtc=active?null:DateTime.UtcNow;e.UpdatedAtUtc=DateTime.UtcNow;await db.SaveChangesAsync(ct);return D(e);}}
